<script setup>import {reactive,ref} from 'vue';import {profile,socialMedia} from '../data/portfolio';const form=reactive({name:'',email:'',subject:'',message:''}),sent=ref(false),error=ref('');const submit=()=>{error.value='';sent.value=false;if(!form.name||!form.email||!form.subject||!form.message)return error.value='Mohon lengkapi seluruh kolom.';if(!/^\S+@\S+\.\S+$/.test(form.email))return error.value='Mohon gunakan alamat email yang valid.';sent.value=true;Object.keys(form).forEach(k=>form[k]='')}</script>
<template><section id="contact" class="section contact"><div class="contact-intro"><p class="eyebrow">08 — CONTACT</p><h2>Punya ide?<br/><em>Mari wujudkan.</em></h2><p>Terbuka untuk kolaborasi, proyek menarik, dan percakapan seputar pendidikan atau teknologi.</p><a :href="`mailto:${profile.email}`" class="contact-email">{{profile.email}} <i class="fa-solid fa-arrow-up-right-from-square"/></a><div class="contact-links"><a :href="`https://wa.me/${profile.whatsapp.replace('+','')}`"><i class="fa-brands fa-whatsapp"/> WhatsApp</a><a v-for="[icon,name,url] in socialMedia" :href="url"><i :class="icon"/> {{name}}</a></div></div><form @submit.prevent="submit"><label>Nama<input v-model.trim="form.name" placeholder="Nama Anda"/></label><label>Email<input v-model.trim="form.email" type="email" placeholder="email@anda.com"/></label><label>Subjek<input v-model.trim="form.subject" placeholder="Tentang apa?"/></label><label>Pesan<textarea v-model.trim="form.message" rows="4" placeholder="Ceritakan kebutuhan Anda..."/></label><p v-if="error" class="form-error">{{error}}</p><p v-if="sent" class="form-success">Terima kasih! Pesan Anda siap dikirim.</p><button class="button primary" type="submit">Kirim Pesan <i class="fa-solid fa-paper-plane"/></button></form></section></template>
